DELETE FROM zona z WHERE z.tipo<>'campus' AND NOT EXISTS (SELECT 1 FROM zona c WHERE c.tipo='campus' AND ST_Intersects(c.geom, z.geom));
DELETE FROM via v WHERE NOT EXISTS (SELECT 1 FROM zona c WHERE c.tipo='campus' AND ST_Intersects(c.geom, v.geom));
DELETE FROM punto p WHERE NOT EXISTS (SELECT 1 FROM zona c WHERE c.tipo='campus' AND ST_DWithin(c.geom::geography, p.geom::geography, 15));
